    @Override
    public List<Check<AccountsRecord>> getChecks() {
        return Arrays.asList(
            Internal.createCheck(this, DSL.name("accounts_default_tax1_percent_check"), "(((default_tax1_percent >= (0)::numeric) AND (default_tax1_percent <= (100)::numeric)))", true),
            Internal.createCheck(this, DSL.name("accounts_default_tax2_percent_check"), "(((default_tax2_percent >= (0)::numeric) AND (default_tax2_percent <= (100)::numeric)))", true),
            Internal.createCheck(this, DSL.name("accounts_duration_format_check"), "((duration_format = ANY (ARRAY['hm'::text, 'decimal'::text])))", true),
            Internal.createCheck(this, DSL.name("accounts_invoice_payment_terms_days_check"), "(((invoice_payment_terms_days >= 0) AND (invoice_payment_terms_days <= 365)))", true),
            Internal.createCheck(this, DSL.name("accounts_status_check"), "((status = ANY (ARRAY['active'::text, 'lapsed'::text, 'pending_deletion'::text])))", true),
            Internal.createCheck(this, DSL.name("accounts_time_rounding_minutes_check"), "((time_rounding_minutes = ANY (ARRAY[0, 6, 15, 30])))", true),
            Internal.createCheck(this, DSL.name("accounts_time_rounding_mode_check"), "((time_rounding_mode = ANY (ARRAY['up'::text, 'nearest'::text])))", true),
            Internal.createCheck(this, DSL.name("accounts_week_start_check"), "(((week_start >= 1) AND (week_start <= 7)))", true)
        );
    }

